#define main preserved_native_main
#include "../nqueen-cuda/main.cu"
#undef main
#include <vector>
std::vector<unsigned char> readbytes(const char*name){FILE*f=fopen(name,"rb");if(!f)exit(3);fseek(f,0,SEEK_END);size_t bytes=ftell(f);rewind(f);std::vector<unsigned char>v(bytes);if(fread(v.data(),1,bytes,f)!=bytes)exit(4);fclose(f);return v;}
int main(){auto raw=readbytes("study_roots.bin"),expected=readbytes("study_expected_u64.bin");unsigned P=raw.size()/16;QueenRoot*roots;unsigned long long*tree,*sol;cudaMalloc(&roots,raw.size());cudaMalloc(&tree,8ull*P);cudaMalloc(&sol,8ull*P);cudaMemcpy(roots,raw.data(),raw.size(),cudaMemcpyHostToDevice);auto launch=[&](){BP_queens_root_dfs<<<(P+127)/128,128>>>(15,P,7,roots,tree,sol);};cudaDeviceSynchronize();launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;bool allok=true;
for(int trial=1;trial<=5;trial++){cudaMemset(tree,0,8ull*P);cudaMemset(sol,0,8ull*P);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::vector<unsigned long long>out(2ull*P);cudaMemcpy(out.data(),tree,8ull*P,cudaMemcpyDeviceToHost);cudaMemcpy(out.data()+P,sol,8ull*P,cudaMemcpyDeviceToHost);bool exact=expected.size()==16ull*P&&memcmp(out.data(),expected.data(),expected.size())==0;unsigned long long err=0;double rel=0;for(size_t j=0;j<out.size();j++){unsigned long long e;memcpy(&e,expected.data()+8*j,8);unsigned long long d=out[j]>=e?out[j]-e:e-out[j];err=std::max(err,d);rel=std::max(rel,double(d)/std::max(double(e),1.));}bool ok=status==cudaSuccess&&exact;allok&=ok;std::vector<unsigned char>got=raw;got.insert(got.end(),(unsigned char*)out.data(),(unsigned char*)(out.data()+out.size()));char name[80];snprintf(name,80,"output_trial%d.bin",trial);FILE*f=fopen(name,"wb");fwrite(got.data(),1,got.size(),f);fclose(f);
printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%llu,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size()/8,err,rel,name,got.size()/8);}return allok?0:1;}
